with lines as (select id, host, level, latency_ms, status_code, attr_key, attr_value from app_logs lateral view outer explode(context) x as attr_key, attr_value) select level, stddev_samp(latency_ms) as latency_ms_stddev, avg(latency_ms) as avg_latency_ms, round(sum(status_code) / nullif(count(case when host = 'h1' then 1 end), 0), 2) as status_code_per_h1, sum(case when host = 'h4' then status_code else 0 end) as h4_status_code, approx_percentile(status_code, 0.95) as status_code_p95 from lines group by level
